begin read only;
select jsonb_build_object('db',current_database(),'server',inet_server_addr(),'user',current_user,'version',version(),'app_tables',(select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and c.relkind in ('r','p','v','m','S','f')),'app_functions',(select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private')),'auth_users',(select count(*) from auth.users),'history',to_regclass('supabase_migrations.schema_migrations'),'extensions',(select jsonb_agg(jsonb_build_object('name',extname,'version',extversion)) from pg_extension));
select jsonb_object_agg(d.defaclobjtype::text,(select jsonb_object_agg((case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end)||':'||a.privilege_type,a.is_grantable) from aclexplode(d.defaclacl)a)) from pg_default_acl d join pg_namespace n on n.oid=d.defaclnamespace where pg_get_userbyid(d.defaclrole)='supabase_admin' and n.nspname='public';
commit;
